import pandas as pd
import csv
from difflib import ndiff
from itertools import zip_longest


def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    try:
        with open(file_path1, 'r', newline='') as f1:
            lines1 = list(csv.reader(f1, delimiter=delimiter, quotechar=quotechar))
        with open(file_path2, 'r', newline='') as f2:
            lines2 = list(csv.reader(f2, delimiter=delimiter, quotechar=quotechar))
    except FileNotFoundError:
        raise FileNotFoundError("One or both of the files cannot be found.")
    except ValueError:
        raise ValueError("One or both of the files is empty.")
    except Exception as e:
        raise Exception(f"IO related error: {e}")

    if not lines1 or not lines2:
        raise ValueError("One or both of the files is empty.")

    records = []
    for line_number, (line1, line2) in enumerate(zip_longest(lines1, lines2), start=1):
        if line1 == line2:
            status = ' '
            content = line1
        elif line1 == '':
            status = '+'
            content = line2
        elif line2 == '':
            status = '-'
            content = line1
        else:
            status = '?'
            content = line1 if line1 != '' else line2
        records.append((line_number, status, content))

    return pd.DataFrame(records, columns=['Line Number', 'Status', 'Content'])

