import warnings
import os
import glob
import shutil
import time


def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    if not os.path.isdir(SOURCE_DIR):
        warnings.warn(f"Source directory '{SOURCE_DIR}' does not exist.", UserWarning)
        return transferred_files

    if not os.path.isdir(DEST_DIR):
        try:
            os.makedirs(DEST_DIR)
        except OSError as exc:
            warnings.warn(
                f"Could not create destination directory '{DEST_DIR}': {exc}",
                UserWarning,
            )
            return transferred_files

    if EXTENSIONS is None:
        extensions = []
    elif isinstance(EXTENSIONS, str):
        extensions = [EXTENSIONS]
    else:
        try:
            extensions = list(EXTENSIONS)
        except TypeError:
            warnings.warn("EXTENSIONS must be a string or an iterable.", UserWarning)
            return transferred_files

    for extension in extensions:
        if not extension:
            continue

        extension = str(extension).strip()
        if not extension.startswith("."):
            extension = "." + extension

        pattern = os.path.join(SOURCE_DIR, f"*{extension}")

        for file_path in glob.glob(pattern):
            if not os.path.isfile(file_path):
                continue

            dest_path = os.path.join(DEST_DIR, os.path.basename(file_path))

            if os.path.abspath(file_path) == os.path.abspath(dest_path):
                continue

            try:
                shutil.copy2(file_path, dest_path)
                transferred_files.append(os.path.basename(dest_path))
            except (OSError, IOError, shutil.SameFileError) as exc:
                warnings.warn(
                    f"Could not transfer '{file_path}' to '{dest_path}': {exc}",
                    UserWarning,
                )

    return transferred_files

