import csv
import os
from collections import Counter

CSV_FILE_PATH = 'match_data.csv'


def create_test_csv(filename, content):
    directory = os.path.dirname(filename)
    if directory:
        os.makedirs(directory, exist_ok=True)
    with open(filename, 'w', newline='') as file:
        writer = csv.writer(file)
        writer.writerows(content)


def setup_csv():
    content = [
        ['team', 'goals', 'penalties'],
        ['Team A', '2', '1'],
        ['Team B', '1', '2'],
        ['Team C', '3', '0']
    ]
    create_test_csv('test_data/test_case_2.csv', content)


def task_func(goals, penalties, csv_file_path=CSV_FILE_PATH):
    count = Counter()

    try:
        with open(csv_file_path, 'r', newline='') as file:
            reader = csv.reader(file)
            rows = list(reader)
    except FileNotFoundError:
        rows = []

    total_goals = 0
    total_penalties = 0

    for row in rows[1:]:
        if len(row) >= 2:
            try:
                total_goals += int(row[1])
            except (ValueError, TypeError):
                pass
        if len(row) >= 3:
            try:
                total_penalties += int(row[2])
            except (ValueError, TypeError):
                pass

    count.update({'goals': total_goals, 'penalties': total_penalties})
    count.update({'goals': goals, 'penalties': penalties})

    return count

