import pandas as pd
import random
from datetime import datetime


def task_func(
    task_list,
    n_tasks,
    employees=["John Doe", "Jane Smith", "James Brown", "Mary Johnson", "Robert Davis"],
    seed=None,
):
    if n_tasks < 0:
        raise ValueError("n_tasks must be non-negative")

    if seed is not None:
        random.seed(seed)

    due_date = datetime.now().strftime("%Y-%m-%d")

    if n_tasks == 0 or not task_list:
        return pd.DataFrame(
            columns=["Task Name", "Assigned To", "Due Date"]
        )

    if n_tasks <= len(task_list):
        selected_tasks = random.sample(task_list, n_tasks)
    else:
        selected_tasks = random.choices(task_list, k=n_tasks)

    data = []
    for task in selected_tasks:
        task_name = str(task).replace(" ", "_")
        assigned_to = random.choice(employees) if employees else "No Employee"
        data.append([task_name, assigned_to, due_date])

    return pd.DataFrame(
        data,
        columns=["Task Name", "Assigned To", "Due Date"]
    )

