import pandas as pd
from datetime import datetime
import random


def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    if not isinstance(epoch_milliseconds, (int, float)):
        raise ValueError("epoch_milliseconds must be a numeric value")
    if epoch_milliseconds < 0:
        raise ValueError("epoch_milliseconds must be non-negative")
    if not isinstance(products, list) or len(products) == 0:
        raise ValueError("products must be a non-empty list of strings")
    if not all(isinstance(product, str) for product in products):
        raise ValueError("all products must be strings")

    seed = random_seed if isinstance(random_seed, int) else 0
    random.seed(seed)

    try:
        start_dt = datetime.fromtimestamp(epoch_milliseconds / 1000)
    except (OverflowError, OSError) as exc:
        raise ValueError("epoch_milliseconds is out of range") from exc

    now = datetime.now()
    start_date = start_dt.date()
    end_date = now.date()

    if start_date > end_date:
        raise ValueError("epoch_milliseconds must not be in the future")

    rows = []
    for day in range(start_date.toordinal(), end_date.toordinal() + 1):
        day_dt = datetime.fromordinal(day)
        for product in products:
            rows.append((product, day_dt, random.randint(10, 50)))

    return pd.DataFrame(rows, columns=["Product", "Date", "Sales"])

